      IF enb = '1' THEN
        Delay1_delOut <= Delay1_ectrl;
      END IF;
    END IF;
  END PROCESS Delay1_lowered_process;


  Delay1_bypass_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Delay1_last_value <= to_unsigned(16#0000#, 16);
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb = '1' THEN
        Delay1_last_value <= Delay1_out1;
      END IF;
    END IF;
  END PROCESS Delay1_bypass_process;


  
  Delay1_out1 <= Delay1_last_value WHEN Delay7_out1 = '0' ELSE
      Delay1_delOut;

  FC_DEBUGOUTTAG_0_debugRdData <= Delay2_Out1_debugRdData;

  FC_DEBUGOUTTAG_0_debugID <= Delay2_Out1_debugID;

END rtl;

